style.css:
@-moz-document domain("youtube.com") {
/* Líneas celestes alrededor de los videos */
  ytd-rich-item-renderer,
  ytd-video-renderer,
  ytd-playlist-renderer {
    border: 2px solid #00ccff !important;
    border-radius: 10px;
    padding: 5px;
    margin-bottom: 10px;
    box-shadow: 0 0 8px rgba(0, 204, 255, 0.5);
    transition: all 0.3s ease-in-out;
  }

  /* Resaltar contenedores al pasar el mouse */
  ytd-rich-item-renderer:hover,
  ytd-video-renderer:hover,
  ytd-playlist-renderer:hover {
    border-color: #00ffff !important;
    box-shadow: 0 0 12px rgba(0, 255, 255, 0.8);
    transform: scale(1.01);
  }

  /* Líneas en la barra superior */
  #masthead-container {
    border-bottom: 3px solid #00ccff !important;
  }

  /* Borde en la caja de búsqueda */
  #search-form {
    border: 2px solid #00ccff !important;
    border-radius: 8px;
    padding: 2px;
  }

  /* Botón de búsqueda con línea */
  #search-icon-legacy {
    border: 2px solid #00ccff !important;
    border-radius: 4px;
  }

  /* Comentarios con bordes celestes */
  ytd-comment-thread-renderer {
    border-left: 3px solid #00ccff;
    padding-left: 10px;
    margin-bottom: 15px;
  }
}
